<?php
// Port of app/surveys.js functions. The survey data itself is surveys.json, generated by app/export-surveys.js.
$_s = json_decode(file_get_contents(__DIR__ . '/surveys.json'), true, 512, JSON_THROW_ON_ERROR);
define('SURVEYS', $_s['SURVEYS']);
define('OPT', $_s['OPT']);
define('LANGS', $_s['LANGS']);
unset($_s);

// JS Number.isInteger for a decoded JSON value (5.0 counts)
function is_jsint($v): bool { return is_int($v) || (is_float($v) && is_finite($v) && floor($v) == $v); }
// JS Math.round: halves go up, also for negatives (PHP round() goes away from zero)
function js_round(float $x): float { $f = floor($x); return $x - $f >= 0.5 ? $f + 1 : $f; }
// JS String(v || '') for a decoded JSON value
function str($v): string {
  if (is_string($v)) return $v;
  if (is_int($v) || is_float($v)) return $v == 0 ? '' : (string) $v;
  return $v === true ? 'true' : '';
}
// JS String.prototype.trim (Unicode spaces + BOM) and slice by characters, without mbstring
function jtrim(string $s): string { return preg_replace('/^[\s\x{FEFF}]+|[\s\x{FEFF}]+$/u', '', $s) ?? trim($s); }
function cut(string $s, int $n): string { return preg_match('/^.{0,' . $n . '}/su', $s, $m) ? $m[0] : substr($s, 0, $n); }

// Validates one submission against its template. Returns null on any invalid or missing answer.
function grade($key, $raw): ?array {
  if (!is_string($key) || !isset(SURVEYS[$key]) || !is_array($raw)) return null;
  $answers = [];
  $sum = 0; $n = 0; $flags = 0; $nps = null;
  foreach (SURVEYS[$key]['q'] as $q) {
    $v = $raw[$q['id']] ?? null;
    if ($q['t'] === 'scale') { if (!is_jsint($v) || $v < 1 || $v > 5) return null; $v = (int) $v; $sum += $v; $n++; }
    elseif ($q['t'] === 'nps') { if (!is_jsint($v) || $v < 0 || $v > 10) return null; $v = (int) $v; $nps = $v; }
    elseif (!in_array($v, $q['opts'], true)) return null;
    if (isset($q['bad']) && $v === $q['bad']) $flags++;
    $answers[$q['id']] = $v;
  }
  return ['answers' => $answers, 'score' => $n ? js_round($sum / $n * 100) / 100 : null, 'nps' => $nps, 'flags' => $flags];
}

// Readable phone label for the admin; see deviceInfo() in app/surveys.js.
function device_info(string $ua, array $dev): array {
  $s = fn($v, $n) => substr(trim(preg_replace('~[^\w .,()\-/+]~', '', str($v))), 0, $n);
  $model = $s($dev['model'] ?? null, 60);
  $os = '';
  $android = preg_match('/Android ([\d.]+)(?:; ([^;)]+))?/', $ua, $a);
  $ios = preg_match('/(iPhone|iPad|iPod).*? OS (\d+)_(\d+)/', $ua, $i);
  if ($android) {
    $pv = $s($dev['platformVersion'] ?? null, 12);
    $os = 'Android ' . ($pv !== '' ? $pv : $a[1]);
    if ($model === '' && ($a[2] ?? '') !== '' && trim($a[2]) !== 'K') $model = $s(preg_replace('~ Build/.*~', '', $a[2]), 60);
  } elseif ($ios) {
    $os = "iOS $i[2].$i[3]";
    if ($model === '') $model = $i[1];
  } elseif (str_contains($ua, 'Windows')) $os = 'Windows';
  elseif (str_contains($ua, 'Mac OS X')) $os = 'macOS';
  elseif (str_contains($ua, 'Linux')) $os = 'Linux';
  foreach (['/^SM-/' => 'Samsung', '/^CPH/' => 'Oppo', '/^RMX/' => 'Realme', '/^V\d{4}/' => 'Vivo', '/^(M\d{4}|2\d{5,})/' => 'Xiaomi'] as $re => $brand) {
    if (preg_match($re, $model)) { $model = "$brand $model"; break; }
  }
  $w = is_jsint($dev['w'] ?? null) && $dev['w'] < 10000 ? (int) $dev['w'] : 0;
  $h = is_jsint($dev['h'] ?? null) && $dev['h'] < 10000 ? (int) $dev['h'] : 0;
  return ['model' => $model !== '' ? $model : ($android ? 'Android' : ($os !== '' ? 'Kompyuter' : 'Nomaʼlum')), 'os' => $os, 'screen' => $w && $h ? "{$w}×{$h}" : ''];
}

// Optional callback number, Uzbek only. Blank → null, valid → '+998XXXXXXXXX', anything else → false (reject).
function clean_phone($v) {
  $d = preg_replace('/\D/', '', is_string($v) || is_int($v) || is_float($v) ? (string) $v : '');
  if ($d === '') return null;
  $n = strlen($d) === 12 && str_starts_with($d, '998') ? substr($d, 3) : $d;
  return preg_match('/^\d{9}\z/', $n) ? '+998' . $n : false;
}
